import math

def prime_pi(n):
    count = 0
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(math.sqrt(i)) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            count += 1
    return count

def valuation(n, p):
    count = 0
    while n > 0 and n % p == 0:
        count += 1
        n //= p
    return count

def omega_K(n):
    if n < 34:
        # For n < 34, N(n)=0, which is <= 4000.
        return 0

    # K = n! / (7 * 17^2)
    primes_n = []
    for i in range(2, n + 1):
        is_prime = True
        for j in range(2, int(math.sqrt(i)) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            primes_n.append(i)

    omega = 0

    # Check prime factors based on formula derivation:
    # Primes p != 7, 17 are always factors if p <= n.
    # Prime 7: v_7(K) = v_7(n!) - 1. Always >= 1 for n >= 17.
    # Prime 17: v_17(K) = v_17(n!) - 2.

    p7_exp = valuation(math.factorial(n), 7) - 1
    p17_exp = valuation(math.factorial(n), 17) - 2

    if p7_exp > 0:
        omega += 1
    if p17_exp > 0:
        omega += 1

    # Count primes p <= n excluding 7 and 17
    for p in primes_n:
        if p != 7 and p != 17:
            omega += 1

    return omega

n = 41
omega_41 = omega_K(n)
N_41 = 2**omega_41
print(f"For n={n}, omega(K) = {omega_41}, N(n) = {N_41}")

def count_primes(n):
    primes = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes.append(p)
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
    return len(primes)

# Test specific values
print(f"pi(34): {count_primes(34)}")
print(f"pi(42): {count_primes(42)}")
print(f"pi(43): {count_primes(43)}")
